const DEFAULT_MAX_TOUR_FILE_BYTES = 2 * 1024 * 1024;
const DEFAULT_MAX_TOUR_LINE_BYTES = 64 * 1024;
const DEFAULT_MAX_STACK_CONTENT_BYTES = 8 * 1024 * 1024;

export interface BuildChangeTourOptions {
    headRef?: string;
    baseRef?: string;
    title?: string;
    sourceUrl?: string;
    generatedAt?: string;
    maxFileBytes?: number;
    maxLineBytes?: number;
    story?: ChangeTourStory;
    source?: ChangeTourSource;
}

interface ChapterDefinition {
    id: string;
    title: string;
    priority: number;
}

const CHAPTERS = {
    context: { id: 'context', title: 'Context and architecture', priority: 0 },
    contracts: { id: 'contracts', title: 'Data model and contracts', priority: 1 },
    behavior: { id: 'behavior', title: 'Behavior and integration', priority: 2 },
    proof: { id: 'proof', title: 'Proof and coverage', priority: 3 },
    packaging: { id: 'packaging', title: 'Packaging and dependencies', priority: 4 }
} satisfies Record<string, ChapterDefinition>;

export function buildChangeTourManifest(
    startPath: string,
    options: BuildChangeTourOptions = {}
): ChangeTourManifest {
    let source = options.source ? parseChangeTourSource(options.source) : undefined;
    const range = resolveBranchReviewRange(startPath, options.headRef ?? source?.range?.head,
        options.baseRef ?? source?.range?.base);
    // Freeze every authored ref before reading any evidence. The same ref must
    // mean the same commit in root chapters and independently authored modes.
    if (source) source = pinTourSource(source, range.repoRoot, new Map([
        [range.headRef, range.headOid], [range.baseRef, range.baseOid]
    ]), range.baseOid, range.headOid);
    const maxFileBytes = options.maxFileBytes ?? DEFAULT_MAX_TOUR_FILE_BYTES;
    const maxLineBytes = options.maxLineBytes ?? DEFAULT_MAX_TOUR_LINE_BYTES;
    const omittedFiles: string[] = [];
    const files: ChangeTourFile[] = [];
    const sceneRecords: Array<{ chapter: ChapterDefinition; scene: ChangeTourDiffScene }> = [];
    let totalAdditions = 0;
    let totalDeletions = 0;
    let totalBinaryFiles = 0;

    for (const changedPath of range.changedPaths) {
        const { additions, deletions, binary } = readGitLineStats(
            range.repoRoot,
            range.mergeBaseOid,
            range.headOid,
            changedPath.path,
            changedPath.previousPath
        );
        totalAdditions += additions;
        totalDeletions += deletions;
        if (binary) totalBinaryFiles += 1;
        const pair = resolveReviewPathPair(range.changedPaths, changedPath.path);
        if (!pair) {
            omittedFiles.push(changedPath.path);
            files.push(buildOmittedFile(changedPath, additions, deletions, 'Git endpoints could not be resolved.'));
            continue;
        }
        const left = readGitText(range.repoRoot, range.mergeBaseOid, pair.leftPath, maxFileBytes, maxLineBytes);
        const right = readGitText(range.repoRoot, range.headOid, pair.rightPath, maxFileBytes, maxLineBytes);
        if (left.kind !== 'text' || right.kind !== 'text') {
            omittedFiles.push(changedPath.path);
            files.push(buildOmittedFile(changedPath, additions, deletions, 'Binary, oversized, or contains an oversized line.'));
            continue;
        }
        const chapter = chapterForPath(changedPath.path);
        const scene: ChangeTourDiffScene = {
            id: `file-${files.length + 1}`,
            kind: 'text-diff',
            title: changedPath.path.split('/').pop() || changedPath.path,
            summary: `${formatChangeKind(changedPath.kind)} ${changedPath.path}.`,
            bullets: [],
            tags: [changedPath.kind, `+${additions}`, `−${deletions}`],
            takeaway: buildSceneNote(changedPath.kind, additions, deletions, changedPath.previousPath),
            path: changedPath.path,
            previousPath: changedPath.previousPath,
            changeKind: changedPath.kind,
            leftLabel: pair.leftPath
                ? `${pair.leftPath} @ ${range.mergeBaseOid.slice(0, 7)}`
                : `${changedPath.path} (absent)`,
            rightLabel: pair.rightPath
                ? `${pair.rightPath} @ ${range.headOid.slice(0, 7)}`
                : `${changedPath.path} (absent)`,
            leftContent: left.content,
            rightContent: right.content,
            additions,
            deletions
        };
        files.push(scene);
        sceneRecords.push({
            chapter,
            scene
        });
    }

    files.sort((left, right) => left.path.localeCompare(right.path));

    sceneRecords.sort((left, right) => (
        left.chapter.priority - right.chapter.priority
        || left.scene.path.localeCompare(right.scene.path)
    ));
    let defaultScenes = sceneRecords.map(({ scene }, index) => ({ ...scene, id: `file-${index + 1}` }));
    if (options.story && source) {
        throw new Error('A change tour can use either a legacy story or a source file, not both.');
    }
    const attention = buildChangeAttention(files.map((file) => ({
        path: file.path,
        previousPath: file.previousPath,
        changeKind: file.changeKind,
        additions: file.additions,
        deletions: file.deletions,
        binary: file.kind === 'omitted',
        headText: file.kind === 'text-diff' ? file.rightContent : undefined,
        symbolHints: file.kind === 'text-diff' ? findDeclarationNames(file.rightContent) : []
    })));
    if (!options.story && !options.source && attention.entryPath) {
        const focusRank = (scenePath: string): number => {
            const index = attention.focusPaths.indexOf(scenePath);
            return index === -1 ? Number.MAX_SAFE_INTEGER : index;
        };
        defaultScenes = [...defaultScenes].sort((left, right) => (
            Number(right.path === attention.entryPath) - Number(left.path === attention.entryPath)
            || focusRank(left.path) - focusRank(right.path)
            || left.id.localeCompare(right.id)
        ));
    }
    const authored = source
        ? applySourceChapters(source, source.chapters, defaultScenes, range.repoRoot, { base: range.mergeBaseOid, head: range.headOid })
        : options.story
        ? applyStory(options.story, defaultScenes)
        : buildGeneratedTourLanding(
            defaultScenes,
            buildChapters(sceneRecords, new Map(defaultScenes.map((scene) => [scene.path, scene.id]))),
            attention,
            {
                changedFiles: range.changedPaths.length,
                binaryFiles: totalBinaryFiles,
                additions: totalAdditions,
                deletions: totalDeletions,
                commitCount: range.commits.length
            }
        );
    const scenes = authored.scenes;
    const chapters = authored.chapters;
    const finalScenes = ('finalScenes' in authored ? authored.finalScenes : scenes) as ChangeTourScene[];
    const finalChapters = ('finalChapters' in authored ? authored.finalChapters : chapters) as ChangeTourChapter[];
    const manifest: ChangeTourManifest = {
        // Only authored v2+ files opt into repository-bound zoom modes. Generated
        // and legacy/story tours retain the portable v1 manifest contract.
        version: source?.version ?? 1,
        title: source?.title || options.story?.title || options.title || `${range.headRef} against ${range.baseRef}`,
        windowTitle: source?.windowTitle,
        opening: source?.opening,
        conclusion: source?.conclusion,
        sourceUrl: source?.sourceUrl || options.story?.sourceUrl || options.sourceUrl,
        generatedAt: options.generatedAt || new Date().toISOString(),
        range: {
            baseRef: range.baseRef,
            headRef: range.headRef,
            mergeBaseOid: range.mergeBaseOid,
            headOid: range.headOid
        },
        summary: {
            changedFiles: range.changedPaths.length,
            includedScenes: scenes.length,
            additions: totalAdditions,
            deletions: totalDeletions,
            commitCount: range.commits.length,
            omittedFiles
        },
        commits: range.commits,
        files,
        chapters,
        scenes,
        ...(source?.details !== undefined ? { details: source.details } : {}),
    };
    const authoredModeTours = source && source.version >= 4
        ? buildAuthoredModeTours(
            source,
            authored as CompiledSourceTour,
            defaultScenes,
            range.repoRoot,
            range.mergeBaseOid,
            range.headOid
        )
        : undefined;
    if (authoredModeTours) manifest.tours = authoredModeTours;
    if (manifest.version >= 2) {
        manifest.repository = { root: range.repoRoot };
        const revisions: ChangeTourStackedScene[] = [];
        for (const scene of scenes) {
            let realStack: ChangeTourStackedScene | undefined;
            if (scene.kind === 'stacked-diff') realStack = scene;
            if (scene.kind === 'deconstructed-diff') {
                const authoredScene = source?.chapters.flatMap((chapter) => chapter.scenes)
                    .find((candidate) => candidate.id === scene.id);
                if (authoredScene?.kind !== 'deconstructed-diff' || !authoredScene.stack) {
                    throw new Error(`Deconstructed scene ${scene.id} requires an explicit real revision stack in v2+.`);
                }
                realStack = buildStackedScene(range.repoRoot, {
                    ...authoredScene,
                    kind: 'stacked-diff',
                    overview: compileSceneOverview(authoredScene.overview, false),
                    stack: authoredScene.stack,
                    files: scene.files.map((file) => file.path),
                    steps: []
                }, files.map((file) => file.path));
                if (realStack.stack[0].oid !== scene.realRange.baseOid
                    || realStack.stack[realStack.stack.length - 1].oid !== scene.realRange.targetOid) {
                    throw new Error(`Deconstructed scene ${scene.id} real stack endpoints must match its explanation range.`);
                }
            }
            if (realStack) {
                if (realStack.stack[0].oid !== range.mergeBaseOid
                    || realStack.stack[realStack.stack.length - 1].oid !== range.headOid) {
                    throw new Error(`Scene ${scene.id} real stack endpoints must match the tour's final diff range.`);
                }
                revisions.push(realStack);
            }
        }
        const explanation = scenes.some((scene) => scene.kind === 'deconstructed-diff');
        const distinctRevisions = revisions.some((scene) => scene.stack.length > 2);
        manifest.zoom = {
            authoredDepth: explanation ? 'explanation' : distinctRevisions ? 'revisions' : 'final',
            modes: [...(explanation ? ['explanation' as const] : []),
                ...(distinctRevisions ? ['revisions' as const] : []), 'final', 'history'],
            revisions,
            final: { scenes: finalScenes, chapters: finalChapters }
        };
    }
    return parseChangeTourManifest(manifest);
}

interface CompiledSourceTour {
    scenes: ChangeTourScene[];
    chapters: ChangeTourChapter[];
    finalScenes: ChangeTourScene[];
    finalChapters: ChangeTourChapter[];
}

function applySourceChapters(
    source: ChangeTourSource,
    chaptersToCompile: ChangeTourSourceChapter[],
    defaultScenes: ChangeTourDiffScene[],
    repoRoot: string,
    imageRevisions: { base: string; head: string }
): CompiledSourceTour {
    const available = new Map(defaultScenes.map((scene) => [scene.path, scene]));
    const resolvedAnchors = new Map<string, ChangeTourResolvedAnchor>();
    for (const [id, anchor] of Object.entries(source.anchors)) {
        const file = available.get(anchor.file);
        if (!file) {
            throw new Error(`Anchor ${id} references a file outside the text change range: ${anchor.file}`);
        }
        const content = anchor.revision === 'base' ? file.leftContent : file.rightContent;
        resolvedAnchors.set(id, resolveAnchor(id, anchor.file, anchor.revision, content, anchor.contains, anchor.occurrence));
    }
    const connections = new Map(source.connections.map((connection) => [connection.id, {
        id: connection.id,
        label: connection.label,
        from: requireResolvedAnchor(resolvedAnchors, connection.from),
        to: requireResolvedAnchor(resolvedAnchors, connection.to)
    }]));
    const scenes: ChangeTourScene[] = [];
    const chapters: ChangeTourChapter[] = [];
    const finalScenes: ChangeTourScene[] = [];
    const finalChapters: ChangeTourChapter[] = [];

    for (const chapter of chaptersToCompile) {
        const sceneIds: string[] = [];
        const finalSceneIds: string[] = [];
        for (const authoredScene of chapter.scenes) {
            if (authoredScene.kind === 'deconstructed-diff') {
                const deconstructedScene = buildDeconstructedManifestScene(
                    repoRoot,
                    authoredScene,
                    authoredScene.base || source.range?.base,
                    authoredScene.target || source.range?.head,
                    [...available.keys()]
                );
                scenes.push(deconstructedScene);
                sceneIds.push(deconstructedScene.id);
                if (authoredScene.steps) {
                    const finalScene = buildWalkthroughManifestScene(
                        { ...authoredScene, steps: authoredScene.steps },
                        available,
                        resolvedAnchors,
                        connections,
                        image => compileTourImage(repoRoot, image, imageRevisions[image.revision])
                    );
                    finalScenes.push(finalScene);
                    finalSceneIds.push(finalScene.id);
                }
                continue;
            }
            if (authoredScene.kind === 'stacked-diff') {
                const stackedScene = buildStackedScene(
                    repoRoot,
                    authoredScene,
                    [...available.keys()]
                );
                scenes.push(stackedScene);
                sceneIds.push(stackedScene.id);
                for (const [index, file] of stackedScene.files.entries()) {
                    const endpoint = available.get(file.path);
                    if (!endpoint) continue;
                    const finalScene = { ...endpoint, id: `${stackedScene.id}-final-${index + 1}`, title: file.path };
                    finalScenes.push(finalScene);
                    finalSceneIds.push(finalScene.id);
                }
                continue;
            }
            const scene = buildWalkthroughManifestScene(authoredScene, available, resolvedAnchors, connections,
                image => compileTourImage(repoRoot, image, imageRevisions[image.revision]));
            scenes.push(scene);
            sceneIds.push(scene.id);
            finalScenes.push(scene);
            finalSceneIds.push(scene.id);
        }
        chapters.push({ id: chapter.id, title: chapter.title, sceneIds });
        finalChapters.push({ id: chapter.id, title: chapter.title, sceneIds: finalSceneIds });
    }

    return { scenes, chapters, finalScenes, finalChapters };
}

/**
 * Compile independently authored mode chapters without borrowing generated
 * scenes from the root tour.  The root chapters remain the compatibility tour;
 * mode tours are emitted only for v4, when the source supplies one or contains
 * enough authored material for an exact legacy fallback.
 */
function buildAuthoredModeTours(
    source: ChangeTourSource,
    root: CompiledSourceTour,
    defaultScenes: ChangeTourDiffScene[],
    repoRoot: string,
    mergeBaseOid: string,
    headOid: string
): ChangeTourTours | undefined {
    const tours: ChangeTourTours = {};

    if (source.tours?.historical) {
        const compiled = applySourceChapters(source, source.tours.historical.chapters, defaultScenes, repoRoot, { base: mergeBaseOid, head: headOid });
        validateHistoricalStackEndpoints(compiled.scenes, mergeBaseOid, headOid);
        tours.historical = {
            opening: source.tours.historical.opening,
            conclusion: source.tours.historical.conclusion,
            chapters: compiled.chapters,
            scenes: compiled.scenes,
            ...(source.tours.historical.details !== undefined ? { details: source.tours.historical.details } : {}),
        };
    } else if (source.version >= 4) {
        const fallback = buildHistoricalFallback(source.chapters, root);
        if (fallback) {
            tours.historical = {
                ...fallback,
                ...(root.scenes.every(scene => scene.kind !== 'deconstructed-diff')
                    ? { opening: source.opening, conclusion: source.conclusion, details: source.details }
                    : {}),
            };
        }
    }

    if (source.tours?.deconstructed) {
        const compiled = applySourceChapters(source, source.tours.deconstructed.chapters, defaultScenes, repoRoot, { base: mergeBaseOid, head: headOid });
        tours.deconstructed = {
            opening: source.tours.deconstructed.opening,
            conclusion: source.tours.deconstructed.conclusion,
            chapters: compiled.chapters,
            scenes: compiled.scenes,
            ...(source.tours.deconstructed.details !== undefined ? { details: source.tours.deconstructed.details } : {}),
        };
    } else if (source.version >= 4 && source.chapters.some((chapter) => (
        chapter.scenes.some((scene) => scene.kind === 'deconstructed-diff')
    ))) {
        // Preserve the existing repository-bound authored result exactly. This fallback is
        // intentionally based on scene ids and chapter order, never inferred
        // by matching files or narrative text across modes.
        tours.deconstructed = {
            opening: source.opening,
            conclusion: source.conclusion,
            details: source.details,
            chapters: root.chapters,
            scenes: root.scenes,
        };
    }

    return tours.historical || tours.deconstructed ? tours : undefined;
}

function validateHistoricalStackEndpoints(
    scenes: readonly ChangeTourScene[],
    mergeBaseOid: string,
    headOid: string
): void {
    for (const scene of scenes) {
        if (scene.kind !== 'stacked-diff') continue;
        if (scene.stack[0].oid !== mergeBaseOid || scene.stack[scene.stack.length - 1].oid !== headOid) {
            throw new Error(`Historical scene ${scene.id} real stack endpoints must match the tour's final diff range.`);
        }
    }
}

function buildHistoricalFallback(
    sourceChapters: ChangeTourSourceChapter[],
    root: CompiledSourceTour
): ChangeTourModeTour | undefined {
    const regularScenes = new Map(root.scenes.map((scene) => [scene.id, scene]));
    const finalScenes = new Map(root.finalScenes.map((scene) => [scene.id, scene]));
    const scenes: ChangeTourScene[] = [];
    const chapters: ChangeTourChapter[] = [];
    for (const chapter of sourceChapters) {
        const sceneIds: string[] = [];
        for (const authoredScene of chapter.scenes) {
            // A deconstructed scene becomes part of Historical only when the
            // source explicitly authored endpoint walkthrough steps.  Its
            // synthetic scene is never copied into this mode.
            const scene = authoredScene.kind === 'deconstructed-diff'
                ? authoredScene.steps ? finalScenes.get(authoredScene.id) : undefined
                : regularScenes.get(authoredScene.id);
            if (!scene) continue;
            scenes.push(scene);
            sceneIds.push(scene.id);
        }
        if (sceneIds.length > 0) chapters.push({ id: chapter.id, title: chapter.title, sceneIds });
    }
    return scenes.length > 0 ? { chapters, scenes } : undefined;
}

function compileSceneOverview(
    overview: ChangeTourSourceSceneOverview | undefined,
    includeComparison = true
): ChangeTourSceneOverview | undefined {
    if (!overview) return undefined;
    return {
        kind: overview.kind,
        ...(overview.purpose === undefined ? {} : { purpose: overview.purpose }),
        ...(overview.path === undefined ? {} : { path: overview.path }),
        ...(includeComparison && overview.comparison ? { comparison: { ...overview.comparison } } : {})
    };
}

function buildWalkthroughManifestScene(
    authoredScene: ChangeTourNarrative & {
        id: string;
        title: string;
        overview?: ChangeTourSourceSceneOverview;
        steps: ChangeTourSourceStep[];
    },
    available: ReadonlyMap<string, ChangeTourDiffScene>,
    resolvedAnchors: ReadonlyMap<string, ChangeTourResolvedAnchor>,
    connections: ReadonlyMap<string, NonNullable<ChangeTourWalkthroughScene['steps'][number]['connection']>>,
    resolveImage: (source: TourImageSource) => TourImage
): ChangeTourWalkthroughScene {
    const overview = compileSceneOverview(authoredScene.overview, false);
    return {
        id: authoredScene.id,
        kind: 'walkthrough',
        title: authoredScene.title,
        summary: authoredScene.summary,
        bullets: authoredScene.bullets,
        tags: authoredScene.tags,
        takeaway: authoredScene.takeaway,
        ...(overview ? { overview } : {}),
        steps: authoredScene.steps.map((step) => {
            const focus = requireResolvedAnchor(resolvedAnchors, step.focus);
            const diff = available.get(focus.path);
            if (!diff) throw new Error(`Step ${step.id} has no text diff for ${focus.path}.`);
            return {
                id: step.id,
                title: step.title,
                body: step.body,
                depth: step.depth,
                requirement: step.requirement,
                ...(step.image ? { image: resolveImage(step.image) } : {}),
                focus,
                connection: step.connection ? connections.get(step.connection) : undefined,
                diff: { ...diff, id: `${authoredScene.id}-${step.id}` }
            };
        })
    };
}

function buildDeconstructedManifestScene(
    repoRoot: string,
    source: Extract<ChangeTourSource['chapters'][number]['scenes'][number], { kind: 'deconstructed-diff' }>,
    baseRef?: string,
    targetRef?: string,
    availableFilePaths: readonly string[] = []
): ChangeTourDeconstructedScene {
    const compiled = buildDeconstructedScene(repoRoot, source, { baseRef, headRef: targetRef });
    const panels = [{
        id: 'explanation-baseline',
        label: 'Explanation baseline',
        role: 'baseline' as const
    }, ...compiled.stages.map((stage, index) => ({
        id: `explanation-stage-${stage.id}`,
        label: `Stage ${index + 1}: ${stage.title}`,
        role: 'stage' as const,
        stageId: stage.id
    }))];
    const materializablePaths = new Set(compiled.baselineFiles.map((file) => file.path));
    const includedPaths = availableFilePaths.length > 0
        ? availableFilePaths.filter((filePath) => materializablePaths.has(filePath)).sort()
        : [...materializablePaths].sort();
    const missingIntroducedPath = compiled.stages
        .flatMap((stage) => stage.introducedFiles)
        .find((filePath) => !includedPaths.includes(filePath));
    if (missingIntroducedPath) {
        throw new Error(`Deconstructed tour file is not renderable: ${missingIntroducedPath}`);
    }
    const introducedPaths = new Set(compiled.stages.flatMap((stage) => stage.introducedFiles));
    let totalContentBytes = 0;
    const files = includedPaths.flatMap((filePath) => {
        const states = [
            compiled.baselineFiles.find((file) => file.path === filePath),
            ...compiled.stages.map((stage) => stage.files.find((file) => file.path === filePath))
        ];
        if (states.some((state) => !state)) {
            throw new Error(`Deconstructed scene ${source.id} is missing virtual state for ${filePath}.`);
        }
        const fileContentBytes = states.reduce((total, state) => (
            total + Buffer.byteLength(state?.content || '', 'utf8')
        ), 0);
        const exceedsFileLimit = states.some((state) => {
            const content = Buffer.from(state?.content || '', 'utf8');
            return content.length > DEFAULT_MAX_TOUR_FILE_BYTES || hasLineLongerThan(content, DEFAULT_MAX_TOUR_LINE_BYTES);
        });
        const exceedsSceneLimit = totalContentBytes + fileContentBytes > DEFAULT_MAX_STACK_CONTENT_BYTES;
        if (exceedsFileLimit || exceedsSceneLimit) {
            if (introducedPaths.has(filePath)) {
                throw new Error(exceedsFileLimit
                    ? `Deconstructed tour file is too large to present: ${filePath}`
                    : `Deconstructed tour content exceeds ${DEFAULT_MAX_STACK_CONTENT_BYTES} bytes.`);
            }
            return [];
        }
        totalContentBytes += fileContentBytes;
        return [{
            path: filePath,
            panels: states.map((state, index) => {
                if (!state) throw new Error(`Missing virtual state for ${filePath}.`);
                return {
                    id: panels[index].id,
                    label: `${panels[index].label} / ${filePath}${state.exists ? '' : ' (absent)'}`,
                    path: state.exists ? filePath : undefined,
                    content: state.content,
                    exists: state.exists
                };
            })
        }];
    });
    if (files.length === 0) throw new Error(`Deconstructed scene ${source.id} has no staged files.`);
    const steps = buildDeconstructedFocusSteps(source.id, compiled.stages, files);
    const overview = compileSceneOverview(source.overview);
    return {
        id: source.id,
        kind: 'deconstructed-diff',
        title: source.title,
        summary: source.summary,
        bullets: source.bullets,
        tags: source.tags,
        takeaway: source.takeaway,
        ...(overview ? { overview } : {}),
        stageLabel: 'Explanation stages',
        realRange: {
            baseRef: baseRef || compiled.baseOid,
            targetRef: targetRef || compiled.targetOid,
            baseOid: compiled.baseOid,
            targetOid: compiled.targetOid
        },
        panels,
        files,
        steps
    };
}

function buildDeconstructedFocusSteps(
    sceneId: string,
    stages: ReturnType<typeof buildDeconstructedScene>['stages'],
    files: ChangeTourDeconstructedScene['files']
): ChangeTourDeconstructedStep[] {
    const reservedIds = new Set(stages.map((stage) => stage.id));
    const usedIds = new Set<string>();
    return stages.flatMap((stage, stageIndex) => {
        const focuses = stage.introducedChanges.flatMap((change) => {
            const file = files.find((candidate) => candidate.path === change.file);
            const left = file?.panels[stageIndex];
            const right = file?.panels[stageIndex + 1];
            if (!file || !left || !right) {
                throw new Error(`Deconstructed scene ${sceneId} is missing comparison state for ${change.file}.`);
            }
            const diffModel = buildTwoWayDiffModel(left.content, right.content);
            const side = left.exists && !right.exists ? 'left' as const : 'right' as const;
            const ranges = buildTourFocusRanges(diffModel, side);
            if (ranges.length === 0) {
                throw new Error(`Deconstructed stage ${stage.id} has no visible change for ${change.file}.`);
            }
            return ranges.map((range) => ({
                file: change.file,
                hunks: change.hunks,
                side,
                ...range
            }));
        });
        return focuses.map((focus, focusIndex) => ({
            id: focusIndex === 0
                ? claimDeconstructedStageId(stage.id, usedIds)
                : claimDeconstructedFocusId(`${stage.id}-focus-${focusIndex + 1}`, reservedIds, usedIds),
            title: focusIndex === 0
                ? stage.title
                : `${focus.file} · Evidence ${focusIndex + 1} of ${focuses.length}`,
            // A stage is one argument supported by multiple code focuses.
            // Keep its explanation once in the reading/narration sequence.
            body: focusIndex === 0 ? stage.narration : '',
            file: focus.file,
            pairIndex: stageIndex,
            side: focus.side,
            startLine: focus.startLine,
            endLine: focus.endLine,
            introducedHunks: [...focus.hunks],
            stageId: stage.id,
            stageIndex,
            focusIndex,
            focusCount: focuses.length
        }));
    });
}

function claimDeconstructedStageId(stageId: string, usedIds: Set<string>): string {
    usedIds.add(stageId);
    return stageId;
}

function claimDeconstructedFocusId(
    preferredId: string,
    reservedIds: ReadonlySet<string>,
    usedIds: Set<string>
): string {
    let candidate = preferredId;
    let suffix = 2;
    while (usedIds.has(candidate) || reservedIds.has(candidate)) {
        candidate = `${preferredId}-${suffix++}`;
    }
    usedIds.add(candidate);
    return candidate;
}

function buildStackedScene(
    repoRoot: string,
    source: Extract<ChangeTourSource['chapters'][number]['scenes'][number], { kind: 'stacked-diff' }>,
    availableFilePaths: readonly string[]
): ChangeTourStackedScene {
    const stack = source.stack.map((entry) => ({
        id: entry.id,
        ref: entry.ref,
        oid: runGitText(repoRoot, ['rev-parse', '--verify', `${entry.ref}^{commit}`]),
        label: entry.label || entry.ref
    }));
    const adjacentChanges = stack.slice(0, -1).map((entry, index) => parseNameStatusZ(execFileSync('git', [
        'diff', '--name-status', '-z', '--find-renames=20%', entry.oid, stack[index + 1].oid
    ], {
        cwd: repoRoot,
        encoding: 'utf8',
        maxBuffer: 16 * 1024 * 1024,
        stdio: ['ignore', 'pipe', 'pipe']
    })));
    const filePaths = [...new Set([
        ...availableFilePaths,
        ...(source.files || []),
        ...source.steps.map((step) => step.file)
    ])].sort();
    if (filePaths.length === 0) throw new Error(`Stacked scene ${source.id} has no changed files.`);

    const requiredFilePaths = new Set([
        ...(source.files || []),
        ...source.steps.map((step) => step.file)
    ]);
    let totalContentBytes = 0;
    const files = filePaths.flatMap((filePath) => {
        const aliases = new Set([filePath]);
        // Starting from a final path, walk backwards through successive renames.
        for (const changes of [...adjacentChanges].reverse()) {
            for (const change of changes) {
                if (aliases.has(change.path) || (change.previousPath && aliases.has(change.previousPath))) {
                    aliases.add(change.path);
                    if (change.previousPath) aliases.add(change.previousPath);
                }
            }
        }
        let fileContentBytes = 0;
        const panels = [];
        for (const entry of stack) {
            const candidates = [...aliases].filter((candidate) => gitBlobExists(repoRoot, entry.oid, candidate));
            if (candidates.length > 1) throw new Error(`Ambiguous revision paths for ${filePath} at ${entry.ref}: ${candidates.join(', ')}`);
            const resolvedPath = candidates[0];
            if (!resolvedPath) {
                panels.push({ id: entry.id, label: `${entry.label} / ${filePath} (missing)`, content: '', exists: false });
                continue;
            }
            const content = readGitText(repoRoot, entry.oid, resolvedPath, DEFAULT_MAX_TOUR_FILE_BYTES, DEFAULT_MAX_TOUR_LINE_BYTES);
            if (content.kind !== 'text') {
                if (requiredFilePaths.has(filePath)) {
                    throw new Error(`Stacked tour file is binary or too large: ${resolvedPath}`);
                }
                return [];
            }
            fileContentBytes += Buffer.byteLength(content.content);
            panels.push({
                id: entry.id,
                label: `${entry.label} / ${resolvedPath}`,
                path: resolvedPath,
                content: content.content,
                exists: true
            });
        }
        totalContentBytes += fileContentBytes;
        if (totalContentBytes > DEFAULT_MAX_STACK_CONTENT_BYTES) {
            throw new Error(`Stacked tour content exceeds ${DEFAULT_MAX_STACK_CONTENT_BYTES} bytes.`);
        }
        return [{ path: filePath, panels }];
    });
    if (files.length === 0) throw new Error(`Stacked scene ${source.id} has no materializable text files.`);
    const stackIds = stack.map((entry) => entry.id);
    const overview = compileSceneOverview(source.overview);
    return {
        id: source.id,
        kind: 'stacked-diff',
        title: source.title,
        summary: source.summary,
        bullets: source.bullets,
        tags: source.tags,
        takeaway: source.takeaway,
        ...(overview ? { overview } : {}),
        stack,
        files,
        steps: source.steps.length === 0 ? stack.slice(0, -1).map((_, pairIndex) => ({
            id: `${source.id}-revision-${pairIndex}`,
            title: '', body: '', file: files[0].path, pairIndex, side: 'right' as const
        })) : source.steps.map((step) => ({
            id: step.id,
            title: step.title,
            body: step.body,
            file: step.file,
            pairIndex: stackIds.indexOf(step.pair[0]),
            side: step.side || 'right',
            startLine: step.lines?.[0],
            endLine: step.lines?.[1]
        }))
    };
}

function gitBlobExists(repoRoot: string, oid: string, relativePath: string): boolean {
    try {
        execFileSync('git', ['cat-file', '-e', `${oid}:${relativePath}`], {
            cwd: repoRoot,
            stdio: ['ignore', 'ignore', 'ignore']
        });
        return true;
    } catch {
        return false;
    }
}

function runGitText(repoRoot: string, args: string[]): string {
    return execFileSync('git', args, {
        cwd: repoRoot,
        encoding: 'utf8',
        stdio: ['ignore', 'pipe', 'pipe']
    }).trim();
}

function resolveAnchor(
    id: string,
    file: string,
    revision: 'base' | 'head',
    content: string,
    needle: string,
    occurrence?: number
): ChangeTourResolvedAnchor {
    const offsets: number[] = [];
    let offset = content.indexOf(needle);
    while (offset >= 0) {
        offsets.push(offset);
        offset = content.indexOf(needle, offset + Math.max(needle.length, 1));
    }
    if (offsets.length === 0) throw new Error(`Anchor ${id} did not match ${file} at ${revision}.`);
    if (occurrence === undefined && offsets.length > 1) {
        throw new Error(`Anchor ${id} matched ${offsets.length} places in ${file}; add occurrence to disambiguate it.`);
    }
    const selected = offsets[(occurrence || 1) - 1];
    if (selected === undefined) throw new Error(`Anchor ${id} occurrence ${occurrence} does not exist in ${file}.`);
    const startLine = content.slice(0, selected).split('\n').length;
    const endLine = startLine + needle.split('\n').length - 1;
    return { id, path: file, revision, startLine, endLine, excerpt: needle };
}

function requireResolvedAnchor(
    anchors: ReadonlyMap<string, ChangeTourResolvedAnchor>,
    id: string
): ChangeTourResolvedAnchor {
    const anchor = anchors.get(id);
    if (!anchor) throw new Error(`Unknown resolved anchor: ${id}`);
    return anchor;
}

function applyStory(
    story: ChangeTourStory,
    defaultScenes: ChangeTourDiffScene[]
): { scenes: ChangeTourScene[]; chapters: ChangeTourChapter[] } {
    const available = new Map(defaultScenes.map((scene) => [scene.path, scene]));
    const scenes: ChangeTourScene[] = [];
    const chapterRecords: Array<{ id: string; title: string; sceneIds: string[] }> = [];
    const chaptersById = new Map<string, { id: string; title: string; sceneIds: string[] }>();
    const addScene = (chapterId: string, chapterTitle: string, scene: ChangeTourScene) => {
        let chapter = chaptersById.get(chapterId);
        if (!chapter) {
            chapter = { id: chapterId, title: chapterTitle, sceneIds: [] };
            chaptersById.set(chapterId, chapter);
            chapterRecords.push(chapter);
        }
        scenes.push(scene);
        chapter.sceneIds.push(scene.id);
    };

    for (const storyScene of story.scenes) {
        const id = `scene-${scenes.length + 1}`;
        if (storyScene.kind === 'discussion') {
            addScene(storyScene.chapterId, storyScene.chapterTitle, {
                id,
                kind: 'discussion',
                title: storyScene.title,
                summary: storyScene.summary,
                bullets: storyScene.bullets,
                tags: storyScene.tags,
                takeaway: storyScene.takeaway
            });
            continue;
        }
        const baseScene = available.get(storyScene.path);
        if (!baseScene) {
            throw new Error(`Story references a file outside the change range: ${storyScene.path}`);
        }
        available.delete(storyScene.path);
        addScene(storyScene.chapterId, storyScene.chapterTitle, {
            ...baseScene,
            id,
            title: storyScene.title || baseScene.title,
            summary: storyScene.summary,
            bullets: storyScene.bullets,
            tags: storyScene.tags,
            takeaway: storyScene.takeaway,
            focusChangeIndex: storyScene.focusChangeIndex
        });
    }

    return { scenes, chapters: chapterRecords };
}

function buildChapters(
    records: Array<{ chapter: ChapterDefinition; scene: ChangeTourDiffScene }>,
    sceneIdByPath: Map<string, string>
): ChangeTourChapter[] {
    const definitions = [...new Map(records.map(({ chapter }) => [chapter.id, chapter])).values()]
        .sort((left, right) => left.priority - right.priority);
    return definitions.map((definition) => ({
        id: definition.id,
        title: definition.title,
        sceneIds: records
            .filter(({ chapter }) => chapter.id === definition.id)
            .map(({ scene }) => sceneIdByPath.get(scene.path))
            .filter((sceneId): sceneId is string => Boolean(sceneId))
    }));
}

function chapterForPath(filePath: string): ChapterDefinition {
    const lower = filePath.toLowerCase();
    const role = classifyChangeFileRole(filePath);
    if (role === 'documentation' || lower.includes('architecture')) {
        return CHAPTERS.context;
    }
    if (role === 'test') {
        return CHAPTERS.proof;
    }
    if (/(^|\/)(models?|schema|types?|contracts?)\.[^/]+$/.test(lower)) {
        return CHAPTERS.contracts;
    }
    if (role === 'dependency' || role === 'generated') {
        return CHAPTERS.packaging;
    }
    return CHAPTERS.behavior;
}

function buildGeneratedTourLanding(
    scenes: ChangeTourDiffScene[],
    chapters: ChangeTourChapter[],
    attention: ReturnType<typeof buildChangeAttention>,
    summary: { changedFiles: number; binaryFiles: number; additions: number; deletions: number; commitCount: number }
): { scenes: ChangeTourScene[]; chapters: ChangeTourChapter[] } {
    const entry = attention.entryPath
        ? `Start here: ${attention.entryPath} — ${attention.entryReason}`
        : `No single entry-point — ${attention.entryReason}`;
    const focus = attention.focusPaths.length > 0
        ? `Pay attention: ${attention.focusPaths.join(', ')}`
        : 'Pay attention: no additional production files were identified.';
    const skipped = attention.backgroundPaths.length + attention.mechanicalPaths.length;
    const overview = {
        id: 'change-overview',
        kind: 'discussion' as const,
        title: 'Change overview',
        summary: `${summary.changedFiles} files (${summary.changedFiles - summary.binaryFiles} text, ${summary.binaryFiles} binary) · +${summary.additions} −${summary.deletions} · ${summary.commitCount} commits`,
        bullets: [entry, focus, `Usually skip on a first pass: ${skipped} file${skipped === 1 ? '' : 's'}. All files remain available.`],
        tags: ['start here', 'first pass'],
        takeaway: attention.entryPath ? `Next: open ${attention.entryPath}.` : 'Next: open the first available textual change.'
    };
    return {
        scenes: [overview, ...scenes],
        chapters: [
            { id: 'start-here', title: 'Start here', sceneIds: [overview.id] },
            ...chapters
        ]
    };
}

function findDeclarationNames(content: string): string[] {
    const names = new Set<string>();
    for (const line of content.split('\n')) {
        const match = line.match(/^\s*(?:export\s+)?(?:default\s+)?(?:async\s+)?(?:function|class|interface|type|enum|const|let|var)\s+([A-Za-z_$][\w$]*)/)
            || line.match(/^\s*(?:async\s+)?(?:class|def)\s+([A-Za-z_]\w*)/);
        if (match) names.add(match[1]);
        if (names.size >= 25) break;
    }
    return [...names];
}

function buildSceneNote(kind: string, additions: number, deletions: number, previousPath?: string): string {
    const label = formatChangeKind(kind);
    const rename = previousPath ? ` from ${previousPath}` : '';
    return `${label}${rename} · +${additions} −${deletions}`;
}

function buildOmittedFile(
    changedPath: GitChangedPath,
    additions: number,
    deletions: number,
    reason: string
): ChangeTourOmittedFile {
    return {
        id: `file-${changedPath.path}`,
        kind: 'omitted',
        title: changedPath.path.split('/').pop() || changedPath.path,
        path: changedPath.path,
        previousPath: changedPath.previousPath,
        changeKind: changedPath.kind,
        additions,
        deletions,
        reason
    };
}

function formatChangeKind(kind: string): string {
    return kind.replace('-', ' ').replace(/^./, (letter) => letter.toUpperCase());
}

type GitTextResult =
    | { kind: 'text'; content: string }
    | { kind: 'binary-or-large'; content: '' };

function readGitText(
    repoRoot: string,
    oid: string,
    relativePath: string | null,
    maxBytes: number,
    maxLineBytes: number
): GitTextResult {
    if (!relativePath) {
        return { kind: 'text', content: '' };
    }
    const size = Number(execFileSync('git', ['cat-file', '-s', `${oid}:${relativePath}`], { cwd: repoRoot, encoding: 'utf8' }).trim());
    if (size > maxBytes) return { kind: 'binary-or-large', content: '' };
    const content = execFileSync('git', ['show', `${oid}:${relativePath}`], {
        cwd: repoRoot,
        encoding: 'buffer',
        maxBuffer: Math.max(maxBytes + 1, DEFAULT_MAX_TOUR_FILE_BYTES + 1),
        stdio: ['ignore', 'pipe', 'pipe']
    });
    if (content.length > maxBytes || content.includes(0) || hasLineLongerThan(content, maxLineBytes)) {
        return { kind: 'binary-or-large', content: '' };
    }
    return { kind: 'text', content: content.toString('utf8') };
}

function hasLineLongerThan(content: Buffer, maxLineBytes: number): boolean {
    let lineStart = 0;
    for (let index = 0; index < content.length; index += 1) {
        if (content[index] !== 10) continue;
        if (index - lineStart > maxLineBytes) return true;
        lineStart = index + 1;
    }
    return content.length - lineStart > maxLineBytes;
}

function readGitLineStats(
    repoRoot: string,
    baseOid: string,
    headOid: string,
    filePath: string,
    previousPath?: string
): { additions: number; deletions: number; binary: boolean } {
    const output = execFileSync('git', [
        'diff',
        '--numstat',
        '--find-renames',
        baseOid,
        headOid,
        '--',
        ...[previousPath, filePath].filter((candidate): candidate is string => Boolean(candidate))
    ], {
        cwd: repoRoot,
        encoding: 'utf8',
        stdio: ['ignore', 'pipe', 'pipe']
    });
    const [additionsText = '0', deletionsText = '0'] = output.trim().split(/\s+/, 3);
    return {
        additions: Number.parseInt(additionsText, 10) || 0,
        deletions: Number.parseInt(deletionsText, 10) || 0,
        binary: additionsText === '-' || deletionsText === '-'
    };
}

export function pinTourSource(
    source: ChangeTourSource, repoRoot: string, resolved: Map<string, string>,
    baseOid: string, headOid: string
): ChangeTourSource {
    const copy: ChangeTourSource = JSON.parse(JSON.stringify(source));
    const pin = (ref: string): string => {
        let oid = resolved.get(ref);
        if (!oid) {
            oid = runGitText(repoRoot, ['rev-parse', '--verify', '--end-of-options', `${ref}^{commit}`]);
            resolved.set(ref, oid);
        }
        return oid;
    };
    copy.range = { base: baseOid, head: headOid };
    const chapters = [...copy.chapters, ...Object.values(copy.tours || {}).flatMap(tour => tour?.chapters || [])];
    for (const chapter of chapters) for (const scene of chapter.scenes) {
        if (scene.kind === 'stacked-diff') for (const entry of scene.stack) {
            entry.label ||= entry.ref;
            entry.ref = pin(entry.ref);
        }
        if (scene.kind === 'deconstructed-diff') {
            scene.base = scene.base ? pin(scene.base) : baseOid;
            scene.target = scene.target ? pin(scene.target) : headOid;
        }
    }
    return copy;
}

function compileTourImage(repoRoot: string, source: TourImageSource, revision: string): TourImage {
    const object = `${revision}:${source.file}`;
    let size: number;
    try {
        size = Number(execFileSync('git', ['cat-file', '-s', object], {
            cwd: repoRoot, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe']
        }).trim());
    } catch {
        throw new Error(`Image ${source.file} is unavailable at pinned revision ${revision}.`);
    }
    if (!Number.isSafeInteger(size) || size < 33 || size > MAX_TOUR_IMAGE_BYTES) {
        throw new Error(`Image ${source.file} must be a PNG of at most 8 MiB.`);
    }
    const bytes = execFileSync('git', ['cat-file', 'blob', object], { cwd: repoRoot, maxBuffer: MAX_TOUR_IMAGE_BYTES });
    validatePngHeader(bytes, source.file);
    return { path: source.file, revision, alt: source.alt, dataUrl: `data:image/png;base64,${bytes.toString('base64')}` };
}

