export function captureTourFeedback(tour: ChangeTourManifest, item: TourReadingItem, view: {
    mode: string;
    location: string;
    displayedEvidence?: TourEvidenceContext | null;
    activePairIndex?: number;
    imageVisible?: boolean;
}) {
